import{_ as d,o as a,c as r,a as e}from"./chunks/framework.Ld7uezS_.js";const c=JSON.parse('{"title":"3. 燃烧和火灾基础知识","description":"","frontmatter":{},"headers":[],"relativePath":"theory/03-combustion-fire.md","filePath":"theory/03-combustion-fire.md","lastUpdated":1787283113000}'),o={name:"theory/03-combustion-fire.md"};function l(i,t,h,n,s,b){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="_3-燃烧和火灾基础知识" tabindex="-1">3. 燃烧和火灾基础知识 <a class="header-anchor" href="#_3-燃烧和火灾基础知识" aria-label="Permalink to &quot;3. 燃烧和火灾基础知识&quot;">​</a></h1><h2 id="本章学习目标" tabindex="-1">本章学习目标 <a class="header-anchor" href="#本章学习目标" aria-label="Permalink to &quot;本章学习目标&quot;">​</a></h2><p>学完本章，你应该能解释燃烧发生的条件，区分 A～F 类火灾，说明闪点/燃点/自燃点差异，并根据灭火原理选择基本处置方法。</p><h2 id="一、燃烧为什么会发生" tabindex="-1">一、燃烧为什么会发生 <a class="header-anchor" href="#一、燃烧为什么会发生" aria-label="Permalink to &quot;一、燃烧为什么会发生&quot;">​</a></h2><p>燃烧是可燃物与氧化剂之间发生的放热反应，常伴随火焰、发光、发烟或温度升高。零基础可以先把它理解成“物质、氧气和足够能量在合适条件下持续反应”。</p><h3 id="燃烧三要素" tabindex="-1">燃烧三要素 <a class="header-anchor" href="#燃烧三要素" aria-label="Permalink to &quot;燃烧三要素&quot;">​</a></h3><ol><li><strong>可燃物</strong>：木材、纸张、汽油蒸气、天然气等能够参与燃烧的物质。</li><li><strong>助燃物/氧化剂</strong>：常见是空气中的氧气，也可能是其他氧化剂。</li><li><strong>引火源</strong>：明火、电弧、电火花、高温表面、摩擦或化学反应放出的热量。</li></ol><p>三者同时存在且达到相互作用条件，燃烧才可能发生。比如一张纸（可燃物）放在空气中（助燃物），即使有空气也不会自己燃烧；只有火柴、火星或高温表面提供足够能量，才可能点燃。把其中任何一个条件去掉，燃烧就可能停止。</p><p>学习和答题时常用“三要素”模型；在更完整的燃烧理论中，还会把<strong>链式反应</strong>作为第四个条件，形成“燃烧四面体”。链式反应可以先理解成：燃烧产生的活性粒子继续参与下一轮反应，使反应不断接续，就像一排多米诺骨牌被连续推倒。部分干粉灭火剂的作用之一，就是让这些反应链中断，所以它不是简单地“把火盖住”。</p><p>灭火的基本思路，就是移走可燃物、隔绝氧化剂、降低温度，或用灭火剂抑制链式反应。现实中几种原理可以同时存在：关闭燃气阀门是隔离，水雾带走热量是冷却，泡沫覆盖液面主要是隔绝空气，干粉还可能产生化学抑制。不要把一种灭火器只记成一种固定原理。</p><blockquote><p><strong>安全边界</strong>：这些温度和分类用于理解与考试判断，不能据此直接判断现场是否安全。现场处置还要看燃烧物数量、通风、建筑条件、灭火器铭牌和单位预案。</p></blockquote><h2 id="二、燃烧三要素和四面体怎样联系" tabindex="-1">二、燃烧三要素和四面体怎样联系 <a class="header-anchor" href="#二、燃烧三要素和四面体怎样联系" aria-label="Permalink to &quot;二、燃烧三要素和四面体怎样联系&quot;">​</a></h2><p>三要素适合入门：可燃物、助燃物和引火源同时存在，燃烧才可能开始。四面体是在此基础上增加“链式反应”，用于解释燃烧为什么能持续扩展。</p><ul><li>移走可燃物，属于隔离燃料；</li><li>减少氧气，属于窒息；</li><li>降低温度，属于冷却；</li><li>干粉等灭火剂抑制活性粒子反应，属于化学抑制。</li></ul><p>实际火灾常同时使用多种原理。例如关闭燃气阀门是隔离，冷却周边设备是冷却，使用适配灭火剂可能同时产生窒息或化学抑制。不要把“灭火剂名称”和“灭火原理”当成一一对应关系。</p><h2 id="二、三个温度概念" tabindex="-1">二、三个温度概念 <a class="header-anchor" href="#二、三个温度概念" aria-label="Permalink to &quot;二、三个温度概念&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>用大白话理解</th><th>例子</th></tr></thead><tbody><tr><td>闪点</td><td>液体挥发出的蒸气遇火源能够“闪一下”的最低温度</td><td>低闪点液体更容易形成可燃蒸气</td></tr><tr><td>燃点</td><td>可燃物被点燃后能够持续燃烧的最低温度</td><td>点火后能不能持续烧起来</td></tr><tr><td>自燃点</td><td>没有外部明火，仅因自身受热或反应就能自行着火的最低温度</td><td>堆积可燃物内部蓄热自燃</td></tr></tbody></table><p>闪点、燃点、自燃点不是同一个概念。可以用“液体加热”来区分：温度到闪点时，挥发出来的蒸气遇到火源可能只在液面上短暂闪一下；继续升温达到燃点后，点火才更可能维持燃烧；如果没有外部火源，物质因内部蓄热达到自燃点而自行着火，就属于自燃风险。闪点越低，通常意味着在较低环境温度下就可能形成危险蒸气，但实际风险还要结合通风、浓度、容器和点火源判断。</p><p>题目问“液体蒸气遇火源闪燃”时，优先想到闪点；问“持续燃烧”时，想到燃点；问“没有外部明火而自行着火”时，想到自燃点。</p><h2 id="三、火灾类别-a-f" tabindex="-1">三、火灾类别 A～F <a class="header-anchor" href="#三、火灾类别-a-f" aria-label="Permalink to &quot;三、火灾类别 A～F&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>燃烧对象</th><th>生活化例子</th><th>处置提醒</th></tr></thead><tbody><tr><td>A</td><td>固体物质</td><td>木材、纸张、棉织物</td><td>通常关注冷却，但要看是否带电</td></tr><tr><td>B</td><td>液体或可熔化固体</td><td>汽油、乙醇、沥青、石蜡</td><td>不要用水柱盲目冲击液面</td></tr><tr><td>C</td><td>气体</td><td>天然气、甲烷、氢气</td><td>优先考虑切断气源和防止爆炸</td></tr><tr><td>D</td><td>金属</td><td>镁、钠、钾等</td><td>必须使用适配金属火灾的灭火剂</td></tr><tr><td>E</td><td>带电火灾</td><td>带电设备、线路燃烧</td><td>先断电；灭火剂和距离要符合要求</td></tr><tr><td>F</td><td>烹饪器具内烹饪物</td><td>动植物油脂</td><td>不要直接泼水，避免油液飞溅扩大</td></tr></tbody></table><p>判断类别时看“正在燃烧的对象”，不要只看场所。例如厨房可能同时出现 A 类固体、E 类电气或 F 类油脂火灾。</p><h2 id="四、火灾发展、特殊燃烧和烟气" tabindex="-1">四、火灾发展、特殊燃烧和烟气 <a class="header-anchor" href="#四、火灾发展、特殊燃烧和烟气" aria-label="Permalink to &quot;四、火灾发展、特殊燃烧和烟气&quot;">​</a></h2><p>除常见有火焰燃烧外，还要认识几个容易混淆的现象：</p><table tabindex="0"><thead><tr><th>现象</th><th>先看什么</th><th>零基础理解</th><th>主要危险和学习边界</th></tr></thead><tbody><tr><td>阴燃</td><td>有没有明显火焰</td><td>没有明显火焰或火焰很弱，但内部仍在缓慢放热</td><td>可能藏在堆物、夹层或织物内部，表面无火不代表已经安全</td></tr><tr><td>闪燃</td><td>是蒸气还是固体整体着火</td><td>可燃蒸气遇到火源后瞬间出现火焰，可能很快消失</td><td>重点是蒸气和点火源，不能与室内轰燃混为一谈</td></tr><tr><td>轰燃</td><td>室内是否快速全面着火</td><td>室内上部热烟气和可燃物受热达到条件后，火焰可能在短时间内全面发展</td><td>温度和热辐射会突然升高，人员不能把它当作普通小火处理</td></tr><tr><td>回燃</td><td>是否为缺氧封闭空间</td><td>缺氧空间内积聚的高温可燃烟气，遇空气和点火源后可能突然燃烧</td><td>开门、破拆或进入前存在高风险，必须由受训专业人员按预案处置</td></tr></tbody></table><p>一个简单的区分方法是先问：<strong>是物体内部慢慢烧，还是蒸气瞬间着火，还是房间整体快速发展，还是缺氧空间开口后突然燃烧？</strong> 这四类现象不能都概括为“突然着火”。</p><p>典型发展可以理解为初起、发展、猛烈和衰减阶段。初起阶段火势和热量相对有限，是在确保安全条件下处置的窗口；随着可燃物、氧气和热量不断交换，火势会扩大，烟气会沿水平方向和楼梯间、竖井等路径向上蔓延。</p><p>烟气不仅影响能见度，还可能含有有毒气体并造成高温灼伤。因此疏散时不能只盯着火焰，要重视烟气方向和安全出口。</p><h2 id="五、四种灭火原理" tabindex="-1">五、四种灭火原理 <a class="header-anchor" href="#五、四种灭火原理" aria-label="Permalink to &quot;五、四种灭火原理&quot;">​</a></h2><ul><li><strong>冷却</strong>：吸收热量，使温度降到燃烧所需条件以下，例如水对一般固体火灾的冷却。</li><li><strong>窒息</strong>：减少氧气或隔绝空气，例如泡沫覆盖液面、二氧化碳置换空气。</li><li><strong>隔离</strong>：移走可燃物或切断燃料，例如关闭燃气阀门、移走周边可燃物。</li><li><strong>化学抑制</strong>：中断燃烧链式反应，例如部分干粉灭火剂。</li></ul><h3 id="场景练习" tabindex="-1">场景练习 <a class="header-anchor" href="#场景练习" aria-label="Permalink to &quot;场景练习&quot;">​</a></h3><p>如果配电箱冒烟并伴有火花：先判断是否带电、报警并按授权断电；不能因为“看起来火不大”就直接泼水。选择灭火器时还要考虑设备、电压和现场标准，不只背“某灭火剂万能”。</p><h2 id="六、自测" tabindex="-1">六、自测 <a class="header-anchor" href="#六、自测" aria-label="Permalink to &quot;六、自测&quot;">​</a></h2><ol><li>油锅着火为什么不能直接泼水？</li><li>A 类和 F 类火灾分别看什么燃烧对象？</li><li>关闭燃气阀门属于哪一种灭火原理？</li><li>“闪一下”和“持续燃烧”分别对应什么温度概念？</li></ol><blockquote><p>参考：<a href="https://xfhyjd.119.gov.cn/zwossread/open1File/FirefightingSkillsAssessmentSystem/2025-11-13/4f0f6d863cf843228b5ce52030b59bb7/16193156145476990d82b-cb9d-43a7-a5f0-522abe3d1f8c%E5%9B%BD%E5%AE%B6%E8%81%8C%E4%B8%9A%E6%8A%80%E8%83%BD%E6%A0%87%E5%87%86%E2%80%94%E2%80%94%E6%B6%88%E9%98%B2%E8%AE%BE%E6%96%BD%E6%93%8D%E4%BD%9C%E5%91%98.pdf" target="_blank" rel="noreferrer">《消防设施操作员国家职业技能标准（2019年版）》</a> 2.2.2；GB/T 4968《火灾分类》。</p></blockquote>',35)])])}const u=d(o,[["render",l]]);export{c as __pageData,u as default};
